 dup=[g for g in groups.values() if len(g)>1]; print(fields,'count',len(dup),'lengths',collections.Counter(map(len,dup)))
 if len(fields)>3:
  for g in dup:print(g)
print('\nEMPLOYEE WEEK SAMPLE')
for r in sorted([r for r in R if r['employee_id']=='65120677783'],key=lambda r:(r['date'],int(r['id']))): print(r)
