"""Calculate monthly payroll from the three source CSV files."""

import ast
import csv
import json
from collections import defaultdict
from datetime import date, timedelta
from decimal import Decimal, ROUND_HALF_UP
from pathlib import Path


DATASET = Path("/app/dataset")


def _read_csv(filename: str) -> list[dict[str, str]]:
    with (DATASET / filename).open(encoding="utf-8", newline="") as stream:
        return list(csv.DictReader(stream))


def _task_ids(value: str) -> list[int]:
    """Recover task lists whose opening or closing bracket was omitted."""
    value = value.strip()
    if not value.startswith("["):
        value = "[" + value
    if not value.endswith("]"):
        value += "]"
    try:
        tasks = ast.literal_eval(value)
    except (ValueError, SyntaxError):
        return []
    if not isinstance(tasks, list):
        return []
    return [task for task in tasks if type(task) is int]


def _billing_month(day: date, weekday: int) -> date:
    """A month starts on its first occurrence of the common payday weekday."""
    first = day.replace(day=1)
    start = first + timedelta(days=(weekday - first.weekday()) % 7)
    if day < start:
        return (first - timedelta(days=1)).replace(day=1)
    return first


def answer() -> dict[str, list[int]]:
    rates = {
        employee["PESEL"]: Decimal(employee["hourly_rate"])
        for employee in _read_csv("employees.csv")
    }
    task_pay = {
        int(task["task_id"]): Decimal(task["pay_per_completion"])
        for task in _read_csv("tasks.csv")
    }

    records = []
    seen = set()
    for row in _read_csv("timesheet.csv"):
        # Duplicate shifts have different record IDs but identical other fields.
        signature = tuple((key, value) for key, value in row.items() if key != "id")
        if signature in seen:
            continue
        seen.add(signature)

        # The employee register is authoritative. Similar-looking unknown IDs
        # have separate, overlapping attendance histories and cannot be merged.
        employee_id = row["employee_id"]
        if employee_id not in rates:
            continue
        try:
            day = date.fromisoformat(row["date"])
        except ValueError:
            # April 31 and June 31 have no supported date correction. Their
            # hours are also absent from the subsequent running salary totals.
            continue
        hours = Decimal(row["hours_worked"])
        if not hours.is_finite() or hours < 0 or hours > 24:
            continue
        records.append((day, employee_id, hours, _task_ids(row["performed_tasks"])))

    if not records:
        return {employee_id: [] for employee_id in rates}

    # The earliest valid record is 2025-03-04, a Tuesday. The resulting starts
    # are March 4, April 1, May 6 and June 3; earlier days belong to the prior
    # billing month. The last month includes the available records only.
    weekday = min(record[0] for record in records).weekday()
    totals = defaultdict(Decimal)
    months = set()
    for day, employee_id, hours, tasks in records:
        month = _billing_month(day, weekday)
        months.add(month)
        # Recompute bonuses from documented task prices, excluding unknown
        # tasks and correcting inconsistent or negative recorded bonuses.
        bonus = sum((task_pay[task] for task in tasks if task in task_pay), Decimal(0))
        totals[employee_id, month] += hours * rates[employee_id] + bonus

    ordered_months = sorted(months)
    return {
        employee_id: [
            int(totals[employee_id, month].quantize(Decimal("1"), rounding=ROUND_HALF_UP))
            for month in ordered_months
        ]
        for employee_id in rates
    }


if __name__ == "__main__":
    with open("/app/answer.json", "w", encoding="utf-8") as stream:
        json.dump(answer(), stream, default=list)
